#!/usr/bin/env bash
# Container registry for lab images (CSI driver, client images), plain HTTP on $REGISTRY_PORT.
# A podman quadlet unit, so that it comes back after reboots. Idempotent.
source "$(dirname "$0")/../lib/remote.sh"

dnf -y -q install podman >/dev/null
mkdir -p /etc/containers/systemd /var/lib/registry
cat >/etc/containers/systemd/registry.container <<EOF
# generated by daos-testlab
[Unit]
Description=Lab container registry

[Container]
Image=docker.io/library/registry:2
PublishPort=$REGISTRY_PORT:5000
Volume=/var/lib/registry:/var/lib/registry:Z

[Service]
Restart=always

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl restart registry
for i in $(seq 1 30); do
	curl -fsS "http://localhost:$REGISTRY_PORT/v2/_catalog" >/dev/null 2>&1 && break
	sleep 2
	[ "$i" = 30 ] && die "registry does not answer"
done
log "registry up: http://$REGISTRY ($(curl -fsS "http://localhost:$REGISTRY_PORT/v2/_catalog"))"
